import type { MicroKey, NutrientProfile } from './nutrients';

export type FoodSource = 'usda' | 'off' | 'custom' | 'local' | 'recipe' | 'manual';

export interface ServingOption {
  label: string;
  grams: number;
}

export interface FoodItem {
  /** Stable reference: 'usda:<fdcId>', 'off:<barcode>', 'custom:<uuid>', 'local:<id>', 'recipe:<id>'. */
  ref: string;
  source: FoodSource;
  name: string;
  brand?: string | null;
  /** Nutrients per 100 g — or per 1 serving when `servingOnly` is true. */
  per100: NutrientProfile;
  servings: ServingOption[];
  /** Default amount: grams, or number of servings when `servingOnly`. */
  defaultGrams: number;
  servingOnly?: boolean;
  /** Short label shown on the result row, e.g. 'USDA SR Legacy'. */
  sourceLabel: string;
  /** Extra caveat about the data, shown in the portion sheet. */
  dataNote?: string;
  category?: string;
  /** USDA FoodData Central ID, when the values come from USDA. */
  fdcId?: number;
}

export const SOURCE_BADGE: Record<FoodSource, { label: string; tone: 'lime' | 'sky' | 'gold' | 'dim' }> = {
  usda: { label: 'USDA', tone: 'lime' },
  off: { label: 'Label', tone: 'sky' },
  custom: { label: 'Mine', tone: 'gold' },
  local: { label: 'USDA', tone: 'lime' },
  recipe: { label: 'Recipe', tone: 'gold' },
  manual: { label: 'Quick add', tone: 'dim' },
};

type Core = { kcal: number; protein: number; carbs: number; fat: number; sugar?: number; fiber?: number; satFat?: number; sodium?: number };

/**
 * A built-in food with values per 100 g copied from the USDA National Nutrient
 * Database for Standard Reference, Legacy Release (SR Legacy, in FoodData
 * Central). `fdcId` is the FoodData Central ID so every number can be checked at
 * https://fdc.nal.usda.gov/food-details/<fdcId>/nutrients. A nutrient that is
 * missing was not reported by USDA for that food (it is not assumed to be zero).
 */
function usda(
  id: string,
  name: string,
  category: string,
  fdcId: number,
  core: Core,
  micros: Partial<Record<MicroKey, number>>,
  servings: ServingOption[],
  defaultGrams?: number,
): FoodItem {
  return {
    ref: `local:${id}`,
    source: 'local',
    name,
    category,
    fdcId,
    per100: {
      kcal: core.kcal,
      protein: core.protein,
      carbs: core.carbs,
      fat: core.fat,
      sugar: core.sugar ?? null,
      fiber: core.fiber ?? null,
      satFat: core.satFat ?? null,
      sodiumMg: core.sodium ?? null,
      micros,
    },
    servings: [{ label: '100 g', grams: 100 }, ...servings],
    defaultGrams: defaultGrams ?? servings[0]?.grams ?? 100,
    sourceLabel: `USDA SR Legacy · FDC ${fdcId}`,
    dataNote: 'Values per 100 g from USDA FoodData Central (SR Legacy). Brands and home recipes vary — use the pack label when you have it.',
  };
}

