/** Diacritic- and case-insensitive match on every word of the query. */
export function matchesQuery(text: string, query: string): boolean {
  const normalize = (s: string) => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '');
  const haystack = normalize(text);
  return normalize(query)
    .split(/\s+/)
    .filter(Boolean)
    .every((word) => haystack.includes(word));
}

export function searchLocalFoods(query: string, limit = 20): FoodItem[] {
  const q = query.trim();
  if (!q) return [];
  return LOCAL_FOODS.filter((food) => matchesQuery(`${food.name} ${food.category ?? ''}`, q)).slice(0, limit);
}

/** Turn a stored diary entry back into something that can be logged again. */
export function foodFromEntry(entry: {
  name: string;
  food_ref?: string | null;
  source?: string | null;
  grams?: number | null;
  servings?: number | null;
  serving_label?: string | null;
  profile: NutrientProfile;
}): FoodItem | null {
  const source = (entry.source as FoodSource | null) ?? 'manual';
  const ref = entry.food_ref || `manual:${entry.name.toLowerCase()}`;
  if (entry.grams && entry.grams > 0) {
    const factor = 100 / entry.grams;
    const per100 = scale(entry.profile, factor);
    return {
      ref,
      source,
      name: entry.name,
      per100,
      servings: [{ label: '100 g', grams: 100 }, { label: entry.serving_label || `${Math.round(entry.grams)} g`, grams: entry.grams }],
      defaultGrams: entry.grams,
      sourceLabel: SOURCE_BADGE[source]?.label ?? 'Logged before',
    };
  }
  const servings = entry.servings && entry.servings > 0 ? entry.servings : 1;
  return {
    ref,
    source,
    name: entry.name,
    per100: scale(entry.profile, 1 / servings),
    servings: [{ label: entry.serving_label || '1 serving', grams: 1 }],
    defaultGrams: 1,
    servingOnly: true,
    sourceLabel: SOURCE_BADGE[source]?.label ?? 'Logged before',
  };
}

function scale(p: NutrientProfile, factor: number): NutrientProfile {
  const micros: NutrientProfile['micros'] = {};
  for (const [key, value] of Object.entries(p.micros)) {
    if (typeof value === 'number') micros[key as MicroKey] = value * factor;
  }
  const n = (v: number | null) => (v == null ? null : v * factor);
  return {
    kcal: p.kcal * factor,
    protein: p.protein * factor,
    carbs: p.carbs * factor,
    fat: p.fat * factor,
    sugar: n(p.sugar),
    fiber: n(p.fiber),
    satFat: n(p.satFat),
    sodiumMg: n(p.sodiumMg),
    micros,
  };
}
